<?php
declare(strict_types=1);namespace MiniErp\Platform;use PDO;final class MultiTenantMigrationPrecheck{public function __construct(private PDO $server,private PDO $main){}public function check(array $tenant,array $migration):array{$id=(int)$tenant['tenant_id'];$db=(string)$tenant['db_name'];$status='READY';$reasons=[];if($migration['target']!=='TENANT'){$status='TARGET_MISMATCH';$reasons[]='TARGET_MISMATCH';}elseif(!$migration['approved']||in_array($migration['risk'],['DESTRUCTIVE','MANUAL_REVIEW'],true)){$status='BLOCKED';$reasons[]='RISK_BLOCKED';}elseif(!preg_match('/^mini_erp_tenant_[1-9][0-9]*$/',$db)||in_array($db,['mini_erp','mysql','information_schema','performance_schema','sys'],true)){$status='BLOCKED';$reasons[]='DB_NAME_INVALID';}elseif($migration['test_only']&&$id<990000){$status='BLOCKED';$reasons[]='TEST_ONLY_TENANT_REQUIRED';}elseif(!in_array((string)$tenant['status'],['ativo','ativa'],true)||!empty($tenant['blocked'])){$status='BLOCKED';$reasons[]='TENANT_INACTIVE';}elseif((int)$this->main->query('SELECT COUNT(*) FROM tenants WHERE db_name='.$this->main->quote($db))->fetchColumn()!==1){$status='BLOCKED';$reasons[]='DATABASE_SHARED';}elseif(!(bool)$this->server->query('SELECT SCHEMA_NAME FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='.$this->server->quote($db))->fetchColumn()){$status='BLOCKED';$reasons[]='DATABASE_MISSING';}else{$pdo=$this->tenant($db);$history=$pdo->query('SELECT migration_id,checksum FROM tenant_schema_migrations')->fetchAll(PDO::FETCH_KEY_PAIR);if(isset($history[$migration['migration_id']]))$status=hash_equals($history[$migration['migration_id']],$migration['checksum'])?'ALREADY_APPLIED':'CHECKSUM_MISMATCH';else{foreach($migration['dependencies'] as $dependency)if(!isset($history[$dependency])){$status='DEPENDENCY_MISSING';$reasons[]=$dependency;break;}if($status==='READY'&&$migration['expected_table']&&(bool)$pdo->query('SHOW TABLES LIKE '.$pdo->quote($migration['expected_table']))->fetchColumn())$status='BASELINE_INCLUDED';}}return['tenant_id'=>$id,'db_name'=>$db,'status'=>$status,'reasons'=>$reasons,'write_performed'=>false];}private function tenant(string $db):PDO{$cfg=require __DIR__.'/../../config.php';$d=$cfg['db'];return new PDO(sprintf('mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4',$d['host'],$d['port'],$db),$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}}
